class Solution {
public:
    int maximizeWin(vector<int>& prizePositions, int k) {
        int n = prizePositions.size();
        int ans = 0, bestLeft = 0, lj = 0, j = 0;
        for (int i = 0; i < n; i++) {
            while (prizePositions[j] < prizePositions[i] - k) {
                while (prizePositions[lj] < prizePositions[j] - k) lj++;
                bestLeft = max(bestLeft, j - lj + 1);
                j++;
            }
            ans = max(ans, (i - j + 1) + bestLeft);
        }
        return ans;
    }
};
